"""Generated by tools/build_gridtools.py from the Field Kit sources.

Edit fieldkit/ in the repository and re-run the builder rather than editing
this copy, or the two will drift apart.
"""

"""Renumber and relabel a sheet layer after it has been moved around by hand."""

from qgis.PyQt.QtCore import QCoreApplication, QVariant
from qgis.core import (
    QgsField,
    QgsProcessing,
    QgsProcessingAlgorithm,
    QgsProcessingException,
    QgsProcessingParameterBoolean,
    QgsProcessingParameterDefinition,
    QgsProcessingParameterEnum,
    QgsProcessingParameterField,
    QgsProcessingParameterFeatureSource,
    QgsProcessingParameterNumber,
    QgsProcessingParameterString,
    QgsProcessingParameterVectorLayer,
    QgsVectorDataProvider,
    QgsWkbTypes,
)

from . import gridmath
from . import gridhelp as _grid

MANAGED_FIELDS = [
    ("sheet_no", QVariant.Int),
    ("sheet_id", QVariant.String),
    ("grid_ref", QVariant.String),
    ("row", QVariant.Int),
    ("col", QVariant.Int),
    ("center_x", QVariant.Double),
    ("center_y", QVariant.Double),
    ("cov_pct", QVariant.Double),
    ("nbr_n", QVariant.String),
    ("nbr_s", QVariant.String),
    ("nbr_e", QVariant.String),
    ("nbr_w", QVariant.String),
]


class RenumberSheets(QgsProcessingAlgorithm):
    """Move sheets wherever you want them, then make the numbering agree."""

    INPUT = "INPUT"
    ORDER = "ORDER"
    START_AT = "START_AT"
    TEMPLATE = "TEMPLATE"
    KEEP_FIELD = "KEEP_FIELD"
    COVERAGE = "COVERAGE"
    BAND_RATIO = "BAND_RATIO"
    UPDATE_NEIGHBOURS = "UPDATE_NEIGHBOURS"

    def initAlgorithm(self, config=None):
        self.addParameter(
            QgsProcessingParameterVectorLayer(
                self.INPUT, "Sheet layer (edited in place)",
                [QgsProcessing.TypeVectorPolygon]
            )
        )
        self.addParameter(
            QgsProcessingParameterEnum(
                self.ORDER, "Sheet order", _grid.ORDER_LABELS, defaultValue=0
            )
        )
        self.addParameter(
            QgsProcessingParameterString(
                self.TEMPLATE, "Sheet id template", defaultValue="C-{n:02d}"
            )
        )
        self.addParameter(
            QgsProcessingParameterNumber(
                self.START_AT, "First sheet number",
                QgsProcessingParameterNumber.Integer, defaultValue=1
            )
        )
        self.addParameter(
            QgsProcessingParameterField(
                self.KEEP_FIELD,
                "Keep the existing id where this field is set (optional)",
                parentLayerParameterName=self.INPUT, optional=True
            )
        )
        self.addParameter(
            QgsProcessingParameterFeatureSource(
                self.COVERAGE, "Recalculate coverage against (optional)",
                [QgsProcessing.TypeVectorPolygon], optional=True
            )
        )

        for param in (
            QgsProcessingParameterNumber(
                self.BAND_RATIO,
                "How far a sheet can sit off its row, as a fraction of a sheet",
                QgsProcessingParameterNumber.Double, defaultValue=0.5,
                minValue=0.01, maxValue=5.0),
            QgsProcessingParameterBoolean(
                self.UPDATE_NEIGHBOURS, "Update the neighbour fields",
                defaultValue=True),
        ):
            param.setFlags(param.flags() | QgsProcessingParameterDefinition.FlagAdvanced)
            self.addParameter(param)

    def flags(self):
        # This one writes to the layer you hand it, so it must not run on a
        # background thread.
        return super().flags() | QgsProcessingAlgorithm.FlagNoThreading

    def processAlgorithm(self, parameters, context, feedback):
        layer = self.parameterAsVectorLayer(parameters, self.INPUT, context)
        if layer is None or not layer.isValid():
            raise QgsProcessingException(self.invalidSourceError(parameters, self.INPUT))
        if layer.geometryType() != QgsWkbTypes.PolygonGeometry:
            raise QgsProcessingException("The sheet layer must be polygons.")

        mode = _grid.order_for(self.parameterAsEnum(parameters, self.ORDER, context))
        template = self.parameterAsString(parameters, self.TEMPLATE, context)
        start_at = self.parameterAsInt(parameters, self.START_AT, context)
        keep_field = self.parameterAsString(parameters, self.KEEP_FIELD, context)
        band_ratio = self.parameterAsDouble(parameters, self.BAND_RATIO, context)
        do_neighbours = self.parameterAsBool(
            parameters, self.UPDATE_NEIGHBOURS, context)
        coverage_source = self.parameterAsSource(parameters, self.COVERAGE, context)

        coverage = None
        if coverage_source is not None:
            coverage = _grid.dissolved_coverage(coverage_source)
            if coverage_source.sourceCrs() != layer.crs():
                feedback.pushWarning(
                    "The coverage layer is in %s but the sheets are in %s. "
                    "Coverage percentages will be wrong until you reproject one "
                    "of them."
                    % (coverage_source.sourceCrs().authid(), layer.crs().authid()))

        items = {}
        existing = {}
        for feature in layer.getFeatures():
            if feedback.isCanceled():
                return {}
            geometry = feature.geometry()
            if geometry is None or geometry.isEmpty():
                continue
            box = geometry.boundingBox()
            centroid = geometry.centroid().asPoint()
            items[feature.id()] = (centroid.x(), centroid.y(),
                                   box.width(), box.height())
            existing[feature.id()] = feature

        if not items:
            raise QgsProcessingException("The sheet layer has no usable geometry.")

        rows = gridmath.band_rows(items, band_ratio, axis="y")
        ordered, _ = gridmath.order_by_position(items, mode, band_ratio)
        neighbours = (gridmath.neighbours_by_position(items, band_ratio)
                      if do_neighbours else {})

        position = {}
        for band_index, band in enumerate(rows):
            for column, key in enumerate(band):
                position[key] = (band_index, column)

        feedback.pushInfo(
            "%d sheet(s) in %d row(s)." % (len(items), len(rows)))

        self._ensure_fields(layer, feedback)
        indexes = {name: layer.fields().indexOf(name) for name, _ in MANAGED_FIELDS}

        was_editing = layer.isEditable()
        if not was_editing and not layer.startEditing():
            raise QgsProcessingException(
                "Cannot edit %s. Check it is not read-only." % layer.name())

        number = start_at
        assigned = {}
        kept = 0
        total = 100.0 / len(ordered)

        try:
            for step, fid in enumerate(ordered):
                if feedback.isCanceled():
                    break
                band_index, column = position[fid]
                row = len(rows) - 1 - band_index

                sheet_id = None
                if keep_field:
                    flag = existing[fid].attribute(keep_field)
                    if flag not in (None, "", 0, "0", False):
                        sheet_id = existing[fid].attribute("sheet_id")
                        kept += 1
                if sheet_id in (None, ""):
                    try:
                        sheet_id = gridmath.format_sheet_id(
                            template, number, row, column, nrows=len(rows))
                    except ValueError as exc:
                        raise QgsProcessingException(str(exc))

                assigned[fid] = sheet_id
                centre = items[fid]
                values = {
                    "sheet_no": number,
                    "sheet_id": sheet_id,
                    "grid_ref": "%s%d" % (gridmath.alpha_label(band_index), column + 1),
                    "row": row,
                    "col": column,
                    "center_x": centre[0],
                    "center_y": centre[1],
                }
                if coverage is not None:
                    values["cov_pct"] = self._coverage_percent(
                        existing[fid].geometry(), coverage)
                for name, value in values.items():
                    layer.changeAttributeValue(fid, indexes[name], value)

                number += 1
                feedback.setProgress(int(step * total))

            if do_neighbours:
                for fid, sides in neighbours.items():
                    for direction in ("n", "s", "e", "w"):
                        other = sides[direction]
                        layer.changeAttributeValue(
                            fid, indexes["nbr_" + direction],
                            assigned.get(other) if other is not None else None)
        except Exception:
            if not was_editing:
                layer.rollBack()
            raise

        if was_editing:
            feedback.pushInfo(
                "The layer was already in edit mode, so the changes are sitting in "
                "the edit buffer - save the layer to keep them, or undo to drop "
                "them.")
        elif not layer.commitChanges():
            errors = "; ".join(layer.commitErrors())
            layer.rollBack()
            raise QgsProcessingException("Could not save the changes: %s" % errors)

        layer.triggerRepaint()
        feedback.pushInfo("%d sheet(s) renumbered from %s." % (len(assigned), start_at))
        if kept:
            feedback.pushInfo("%d sheet(s) kept their existing id." % kept)

        return {"OUTPUT": layer.id(), "SHEET_COUNT": len(assigned)}

    @staticmethod
    def _coverage_percent(geometry, coverage):
        if geometry is None or geometry.isEmpty():
            return 0.0
        area = geometry.area()
        if not area:
            return 0.0
        overlap = geometry.intersection(coverage)
        if overlap is None or overlap.isEmpty():
            return 0.0
        return overlap.area() / area * 100.0

    @staticmethod
    def _ensure_fields(layer, feedback):
        """Add any of the managed fields the layer doesn't have yet."""
        missing = [
            QgsField(name, kind) for name, kind in MANAGED_FIELDS
            if layer.fields().indexOf(name) < 0
        ]
        if not missing:
            return
        provider = layer.dataProvider()
        if not provider.capabilities() & QgsVectorDataProvider.AddAttributes:
            raise QgsProcessingException(
                "%s cannot take new fields, and it is missing %s. Save it as a "
                "GeoPackage first."
                % (layer.name(), ", ".join(f.name() for f in missing)))
        if layer.isEditable():
            raise QgsProcessingException(
                "%s is missing the fields %s and is currently in edit mode. Save "
                "or discard your edits first so the fields can be added."
                % (layer.name(), ", ".join(f.name() for f in missing)))
        if not provider.addAttributes(missing):
            raise QgsProcessingException(
                "Could not add the fields %s to %s."
                % (", ".join(f.name() for f in missing), layer.name()))
        layer.updateFields()
        feedback.pushInfo(
            "Added missing field(s): %s" % ", ".join(f.name() for f in missing))

    def name(self):
        return "renumbersheets"

    def displayName(self):
        return "Renumber sheets"

    def group(self):
        return "Sheets"

    def groupId(self):
        return "sheets"

    def shortHelpString(self):
        return (
            "<p>Reads the sheet layer's numbering back off the sheets' positions, "
            "so you can build a grid, drag the sheets wherever the job actually "
            "needs them, add or delete a few, and then make the labels agree.</p>"
            "<p>This one <b>edits the layer you give it</b> rather than producing a "
            "copy - that is the whole point, since you will run it repeatedly on "
            "the same layer. Missing fields are added automatically.</p>"
            "<h3>How rows are worked out</h3>"
            "<p>Row and column from the original grid stop meaning anything the "
            "moment a sheet is dragged, so rows are re-derived from position. A "
            "sheet stays in its row until its centre moves more than half a sheet "
            "away from the row - nudge one sideways and nothing changes, drop one a "
            "full sheet down and it starts a new row. The advanced band setting "
            "loosens or tightens that.</p>"
            "<h3>Keeping a custom label</h3>"
            "<p>Point <i>Keep the existing id</i> at a field - anything non-empty "
            "and non-zero in it means \"leave this sheet's id alone\". Add a "
            "<i>locked</i> integer field, put 1 in it, and that sheet keeps the id "
            "you typed while everything around it renumbers.</p>"
            "<p>Neighbour fields are rebuilt from the new positions, so match-line "
            "callouts stay right. They always come from rows on the ground, not "
            "from the numbering order.</p>"
        )

    def createInstance(self):
        return RenumberSheets()

    def tr(self, string):
        return QCoreApplication.translate("FieldKit", string)
